package com.shopsphere.controller;import com.shopsphere.model.*;import com.shopsphere.repository.UserRepository;import com.shopsphere.security.JwtService;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/auth") public class AuthController{private final UserRepository users;private final PasswordEncoder enc;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;}record Credentials(String email,String password){}record Registration(String name,String email,String password){}@PostMapping("/login")public ResponseEntity<?> login(@RequestBody Credentials c){AppUser u=users.findByEmail(c.email().toLowerCase()).orElse(null);if(u==null||!enc.matches(c.password(),u.getPassword()))return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));return ResponseEntity.ok(payload(u));}@PostMapping("/register")public ResponseEntity<?> register(@RequestBody Registration r){if(r.name()==null||r.name().isBlank()||r.password()==null||r.password().length()<8)return ResponseEntity.badRequest().body(Map.of("message","Name is required and password must be at least 8 characters"));String email=r.email().toLowerCase();if(users.existsByEmail(email))return ResponseEntity.badRequest().body(Map.of("message","Email is already registered"));return ResponseEntity.status(201).body(payload(users.save(new AppUser(r.name().trim(),email,enc.encode(r.password()),Role.CUSTOMER))));}private Map<String,Object> payload(AppUser u){return Map.of("token",jwt.generate(u.getEmail(),u.getRole().name()),"user",Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole().name(),"createdAt",u.getCreatedAt()));}}